/**
 * @suppress
 */
public object FfiConverterTypeCaptureError : FfiConverterRustBuffer<CaptureException> {
    override fun read(buf: ByteBuffer): CaptureException {
        

        return when(buf.getInt()) {
            1 -> CaptureException.TrackingDisabled()
            2 -> CaptureException.SampledOut()
            3 -> CaptureException.Excluded()
            4 -> CaptureException.InvalidField(
                FfiConverterString.read(buf),
                )
            5 -> CaptureException.EmptyQueue()
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: CaptureException): ULong {
        return when(value) {
            is CaptureException.TrackingDisabled -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is CaptureException.SampledOut -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is CaptureException.Excluded -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is CaptureException.InvalidField -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`message`)
            )
            is CaptureException.EmptyQueue -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
        }
    }

    override fun write(value: CaptureException, buf: ByteBuffer) {
        when(value) {
            is CaptureException.TrackingDisabled -> {
                buf.putInt(1)
                Unit
            }
            is CaptureException.SampledOut -> {
                buf.putInt(2)
                Unit
            }
            is CaptureException.Excluded -> {
                buf.putInt(3)
                Unit
            }
            is CaptureException.InvalidField -> {
                buf.putInt(4)
                FfiConverterString.write(value.`message`, buf)
                Unit
            }
            is CaptureException.EmptyQueue -> {
                buf.putInt(5)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}





